  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "In monkeys, mithramycin showed a low CSF:plasma ratio of 0.12 and little brain distribution, indicating poor CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "In humans, daptomycin was undetectable in CSF despite substantial serum concentrations, demonstrating inadequate CNS penetration after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "In mice, colistin showed very low brain-to-plasma ratios of 0.021–0.037 after subcutaneous administration, indicating minimal brain uptake.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred experimental evidence consistently indicates poor CNS penetration after systemic administration, with low CSF/plasma ratios, undetectable CSF levels, and very low brain-to-plasma ratios. No evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "Most records come from different molecules, but assay-transfer scores are high and the direction is consistent across species and routes.",
    "Some meningitis-state records show increased CSF penetration, but these reflect disrupted-barrier conditions and are generally still considered inadequate."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

